) AS v(id, display_name, showdown_id)
WHERE t.id = v.id;

ALTER TABLE public.species ALTER COLUMN display_name SET NOT NULL;
ALTER TABLE public.pokemon ALTER COLUMN display_name SET NOT NULL;
ALTER TABLE public.move ALTER COLUMN display_name SET NOT NULL;
ALTER TABLE public.ability ALTER COLUMN display_name SET NOT NULL;

ALTER TABLE public.pokemon ADD CONSTRAINT pokemon_showdown_id_key UNIQUE (showdown_id);
ALTER TABLE public.move ADD CONSTRAINT move_showdown_id_key UNIQUE (showdown_id);
ALTER TABLE public.ability ADD CONSTRAINT ability_showdown_id_key UNIQUE (showdown_id);
ALTER TABLE public.pokemon ADD CONSTRAINT pokemon_battle_only_base_id_fkey
  FOREIGN KEY (battle_only_base_id) REFERENCES public.pokemon (id);
ALTER TABLE public.pokemon ADD CONSTRAINT pokemon_required_item_id_fkey
  FOREIGN KEY (required_item_id) REFERENCES public.item (id);

COMMIT;
